<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use PHPUnit\Framework\MockObject\MockObject;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\WebAuthnChallenge;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Exception\WebAuthnException;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\FinishRegistration\FinishRegistrationUsecase;
use Civi\Lughauth\Features\Oidc\WebAuthn\Infrastructure\Service\WebAuthnVerifier;

#[AllowMockObjectsWithoutExpectations]

final class FinishRegistrationUsecaseUnitTest extends TestCase
{
    private TenantReadGateway&MockObject $tenants;
    private UserReadGateway&MockObject $users;
    private WebAuthnChallengeGateway&MockObject $challengeGateway;
    private WebAuthnCredentialGateway&MockObject $credentialGateway;
    private WebAuthnVerifier&MockObject $verifier;
    private FinishRegistrationUsecase $usecase;

    protected function setUp(): void
    {
        $this->tenants = $this->createMock(TenantReadGateway::class);
        $this->users = $this->createMock(UserReadGateway::class);
        $this->challengeGateway = $this->createMock(WebAuthnChallengeGateway::class);
        $this->credentialGateway = $this->createMock(WebAuthnCredentialGateway::class);
        $this->verifier = $this->createMock(WebAuthnVerifier::class);

        $this->usecase = new FinishRegistrationUsecase(
            $this->tenants,
            $this->users,
            $this->challengeGateway,
            $this->credentialGateway,
            $this->verifier,
        );
    }

    public function test_valid_attestation_persists_credential(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $user = $this->buildUser('user-uid', 'tenant-uid', 'alice@acme.com', 'Alice');
        $challenge = $this->buildChallenge('+5 minutes', 'user-uid');

        $this->tenants->method('findOneByName')->willReturn($tenant);
        $this->challengeGateway->method('findById')->willReturn($challenge);
        $this->users->method('findOneByUid')->willReturn($user);
        $this->verifier->method('verifyRegistration')->willReturn([
            'credentialId' => 'base64url-cred-id',
            'publicKey' => '-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQ==\n-----END PUBLIC KEY-----',
            'signCount' => 0,
            'aaguid' => null,
            'transports' => ['internal'],
        ]);

        $this->credentialGateway->expects($this->once())
            ->method('store')
            ->with($this->callback(function ($cred) {
                return $cred->credentialId === 'base64url-cred-id'
                    && $cred->userUid === 'user-uid'
                    && $cred->tenantId === 'tenant-uid'
                    && $cred->enabled === true;
            }));

        $this->usecase->finish(
            'challenge-id',
            'acme',
            ['id' => 'cred', 'response' => []],
            'https://acme.example.com',
            'acme.example.com',
        );
    }

    public function test_throws_when_challenge_expired(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $challenge = $this->buildChallenge('-1 minute', 'user-uid');
        $this->challengeGateway->method('findById')->willReturn($challenge);
        $this->users->method('findOneByUid')->willReturn($this->buildUser('u', 'tid', 'a@a.com', 'A'));

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('cid', 'acme', [], 'https://x.com', 'x.com');
    }

    public function test_throws_when_challenge_type_wrong(): void
    {
        $this->tenants->method('findOneByName')->willReturn($this->buildTenant('tid', 'acme'));
        $challenge = new WebAuthnChallenge(
            challengeId: 'cid',
            tenantId: 'tid',
            userUid: 'u',
            challenge: 'abc',
            type: 'authenticate',
            optionsJson: null,
            createdAt: new DateTimeImmutable(),
            expiresAt: new DateTimeImmutable('+5 minutes'),
            verified: false,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        );
        $this->challengeGateway->method('findById')->willReturn($challenge);
        $this->users->method('findOneByUid')->willReturn($this->buildUser('u', 'tid', 'a@a.com', 'A'));

        $this->expectException(WebAuthnException::class);
        $this->usecase->finish('cid', 'acme', [], 'https://x.com', 'x.com');
    }

    private function buildTenant(string $uid, string $name): Tenant&MockObject
    {
        $tenant = $this->createMock(Tenant::class);
        $tenant->method('uid')->willReturn($uid);
        $tenant->method('getName')->willReturn($name);
        return $tenant;
    }

    private function buildUser(string $uid, string $tenantUid, string $email, string $name): User&MockObject
    {
        $tenantRef = $this->createMock(\Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef::class);
        $tenantRef->method('uid')->willReturn($tenantUid);

        $user = $this->createMock(User::class);
        $user->method('uid')->willReturn($uid);
        $user->method('getTenant')->willReturn($tenantRef);
        $user->method('getEmail')->willReturn($email);
        $user->method('getName')->willReturn($name);
        return $user;
    }

    private function buildChallenge(string $expiresIn, string $userUid): WebAuthnChallenge
    {
        return new WebAuthnChallenge(
            challengeId: 'challenge-id',
            tenantId: 'tenant-uid',
            userUid: $userUid,
            challenge: 'abc123',
            type: 'register',
            optionsJson: null,
            createdAt: new DateTimeImmutable(),
            expiresAt: new DateTimeImmutable($expiresIn),
            verified: false,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        );
    }
}
